//  StockCatalog.swift — the film and paper library, read from the bundle.
//
//  `Resources/StockCatalog.json` is generated by `Tools/gen-catalog.py` from
//  the engine's profile directory, so the picker cannot list a stock the
//  engine does not have. Regenerate it when a profile is added.

import Foundation

struct Stock: Codable, Identifiable, Hashable, Sendable {
    let id: String
    let name: String
    let stage: String          // "filming" | "printing"
    let use: String            // "still" | "cine"
    let type: String?
    let targetPrint: String?
    let hasPreviewLUT: Bool
    let pairedFilm: String?
    let cover: String?
    let nominalSpeed: Int?
    let speedUnit: String?
    let speedSource: String?
    var channelModel: String? = nil

    var speedLabel: String? {
        guard isFilm, let nominalSpeed else { return nil }
        return "\(speedUnit ?? "ISO") \(nominalSpeed)"
    }

    var isFilm: Bool { stage == "filming" }
    var isPaper: Bool { stage == "printing" }
    var isMonochrome: Bool { channelModel == "bw" || channelModel == "monochrome" || channelModel == "chromogenic_monochrome" }
    var isCine: Bool { use == "cine" }
    /// A reversal (slide) film: Provia, Velvia, Ektachrome, Kodachrome.
    ///
    /// The catalogue has carried this since it was generated — `type` is
    /// `"positive"` or `"negative"` and the four slide films are the ones
    /// with no `targetPrint` — and nothing read it. A positive is already a
    /// viewable image, so printing one onto a paper stock is an operation the
    /// engine performs happily and nobody wants.
    var isPositive: Bool { type == "positive" }
    /// Stable catalog identity, independent of localized display names.
    var isLocalExperimental: Bool { isFilm && id.hasSuffix("_experimental") }
    var isFotufilm: Bool { isFilm && id.hasSuffix("_fotufilm") }
    var isExperimental: Bool { isLocalExperimental || isFotufilm }
    var displayName: String {
        let suffix = " (Fotufilm)"
        return isFotufilm && name.hasSuffix(suffix) ? String(name.dropLast(suffix.count)) : name
    }
    var brand: String { name.split(separator: " ").first.map(String.init) ?? "" }
    /// Generated packaging artwork, separate from legacy catalog cover metadata.
    var packagingArtworkURL: URL? {
        let baseID: String
        switch id {
        case "kodak_portra_800_push1", "kodak_portra_800_push2": baseID = "kodak_portra_800"
        case "cinestill_800t_fotufilm": baseID = "cinestill_800t"
        case "fujifilm_acros_100_ii_fotufilm": baseID = "fujifilm_neopan_acros_100_ii"
        case "ilford_hp5_plus_fotufilm": baseID = "ilford_hp5_plus_400"
        case "kodak_tmax_100_fotufilm": baseID = "kodak_tmax_100"
        default: baseID = id
        }
        let version = baseID == "kodak_portra_400" ? "v2" : "v1"
        return StockCatalog.bundle.url(forResource: baseID + "-packaging-" + version,
                                       withExtension: "png", subdirectory: StockCatalog.resourceDirectory + (isLocalExperimental ? "/LocalMaterials/FilmCovers" : "/FilmCovers"))
    }
    var coverURL: URL? {
        cover.flatMap { StockCatalog.bundle.url(forResource: $0, withExtension: nil, subdirectory: StockCatalog.resourceDirectory + "/FilmCovers") }
    }
}

struct StockCatalog: Sendable {
    let stocks: [Stock]

    /// The bundle that carries Resources/: the app, or the test bundle.
    static var bundle: Bundle { Bundle(for: BundleToken.self) }
    // A root folder named Resources makes Foundation infer an old-style macOS
    // bundle on iOS. Keep the catalogue shared with a platform-specific root.
    static var resourceDirectory: String {
#if os(iOS)
        "AppResources"
#else
        "Resources"
#endif
    }
    private final class BundleToken {}

    static let shared: StockCatalog = {
        let url = bundle.url(forResource: "StockCatalog", withExtension: "json", subdirectory: resourceDirectory)
        if let url, let data = try? Data(contentsOf: url),
           let decoded = try? JSONDecoder().decode(Wrapper.self, from: data) {
            let localURL = bundle.url(forResource: "StockCatalog", withExtension: "json",
                                      subdirectory: resourceDirectory + "/LocalMaterials")
            let local = localURL.flatMap { try? Data(contentsOf: $0) }
                .flatMap { try? JSONDecoder().decode(Wrapper.self, from: $0) }?.stocks ?? []
            let publicIDs = Set(decoded.stocks.map(\.id))
            return StockCatalog(stocks: decoded.stocks + local.filter {
                $0.isLocalExperimental && !publicIDs.contains($0.id)
            })
        }
        return StockCatalog(stocks: [])
    }()

    private struct Wrapper: Decodable { let stocks: [Stock] }

    /// A fingerprint of the *currently staged* material data. This never
    /// identifies the materials that rendered an old sidecar, nor the engine
    /// executable, and is not used to choose a profile at runtime.
    static let materialPackFingerprint: String? = {
        guard let url = bundle.url(forResource: "material-pack-fingerprint", withExtension: "json",
                                   subdirectory: resourceDirectory + "/engine"),
              let bytes = try? Data(contentsOf: url) else { return nil }
        return parseMaterialPackFingerprint(bytes)
    }()

    static func parseMaterialPackFingerprint(_ bytes: Data) -> String? {
        struct Manifest: Decodable { let algorithm: String; let sha256: String }
        guard let manifest = try? JSONDecoder().decode(Manifest.self, from: bytes),
              manifest.algorithm == "silverphase-material-pack-v1",
              manifest.sha256.utf8.count == 64,
              manifest.sha256.utf8.allSatisfy({ (48...57).contains($0) || (97...102).contains($0) })
        else { return nil }
        return manifest.sha256
    }


    var films: [Stock] { stocks.filter(\.isFilm) }
    var papers: [Stock] { stocks.filter(\.isPaper) }
    static func canonicalID(_ id: String) -> String {
        switch id {
        case "kodak_tri_x_400_experimental": return "kodak_tri_x_400"
        case "ilford_hp5_plus_400_experimental": return "ilford_hp5_plus_400"
        case "silverphase_neutral_bw_print_experimental": return "ilford_multigrade_iv_rc"
        default: return id
        }
    }
    func stock(_ id: String) -> Stock? { stocks.first { $0.id == Self.canonicalID(id) } }

    /// Films in the order the picker shows them: still first, brand-grouped,
    /// then cine. Within a brand the order is the catalog's (alphabetical).
    var filmsForPicker: [Stock] {
        let still = films.filter { !$0.isCine }
        let cine = films.filter(\.isCine)
        return still + cine
    }

    /// Films grouped as v3 draws them: **Positive**, then **Negative**.
    ///
    /// Grouped on `type`, which the catalogue has carried since it was
    /// generated — not on the name and not on the artwork's order, which is
    /// handoff §8.6's requirement. Within each group `filmsForPicker`'s order
    /// is kept, so a cine stock still follows the stills of its group rather
    /// than being hoisted.
    ///
    /// The whole catalogue comes back: v3's illustration shows 3 positive and
    /// 4 negative rows, and those are the counts of a *viewport*, not a
    /// filter.
    var filmGroups: [(title: String, films: [Stock])] {
        let ordered = filmsForPicker
        var groups = [("Positive", ordered.filter { $0.isPositive && !$0.isExperimental }),
                      ("Negative", ordered.filter { !$0.isPositive && !$0.isExperimental })]
        let experimental = ordered.filter(\.isExperimental)
        if !experimental.isEmpty { groups.append(("Experimental", experimental)) }
        return groups
    }

    /// Papers grouped for the picker: Still, then Cine.
    var paperGroups: [(title: String, papers: [Stock])] {
        [("Still", papers.filter { !$0.isCine }), ("Cine", papers.filter(\.isCine))]
    }

    /// Whether `paper` is the declared target of `film` — an honest pairing
    /// versus an approximation (API-SPEC §2's pairing note).
    func isDeclaredPairing(film: String, paper: String) -> Bool {
        stock(film)?.targetPrint == paper
    }
}
